import csv, json
from collections import Counter

rows = list(csv.DictReader(open('/app/input/letter_lines.csv')))

cl_subjects = {
    'addressee': 'CL-301',
    'request': 'CL-302',
    'enclosure': 'CL-303',
    'salutation': 'CL-304',
    'copies': 'CL-305',
    'delivery': 'CL-306',
    'tone': 'CL-307',
    'behavioural_plan': 'CL-308',
    'concern': 'CL-309',
    'interim_contact': 'CL-310',
    'without_prejudice': 'CL-311',
}
oi_subjects = {
    'right_of_first_refusal': 'OI-202',
    'children_named': 'OI-203',
    'overnight_stays': 'OI-204',
    'inconsistent_accounts': 'OI-205',
    'sender_signature': 'OI-211',
}

def verdict(subject, position):
    if subject in cl_subjects:
        if subject == 'addressee':
            return 'VERIFIED' if position in {"mother's attorney", 'mother'} else 'AT_ODDS'
        if subject == 'request':
            return 'VERIFIED' if position in {
                'CL match', 'CL wording exact', 'CL wording paraphrase',
                'neither child overnight unless father present',
                'no overnight stays in her care unless the father is present',
                'no overnight stays unless father present',
                'no overnight unless father present',
            } else 'AT_ODDS'
        if subject == 'enclosure':
            return 'VERIFIED' if position in {
                'a certified copy of the custodial plan', 'certified',
                'certified copy', 'certified copy enclosed',
            } else 'AT_ODDS'
        if subject == 'salutation':
            return 'VERIFIED' if position == 'Dear Counsel' else 'AT_ODDS'
        if subject == 'copies':
            return 'VERIFIED' if position in {'copy nobody', 'nobody'} else 'AT_ODDS'
        if subject == 'delivery':
            return 'VERIFIED' if position in {'by post', 'post'} else 'AT_ODDS'
        if subject == 'tone':
            return 'VERIFIED' if position == 'firm formal brief' else 'AT_ODDS'
        if subject == 'concern':
            return 'VERIFIED' if position in {
                'position only', 'position limb only',
                'narrower concern only position',
            } else 'AT_ODDS'
        if subject == 'behavioural_plan':
            return 'VERIFIED' if position in {
                'full CL match', 'CL match confidence-only setback',
                'confidence stability peer confidence-only',
            } else 'AT_ODDS'
        if subject == 'interim_contact':
            return 'VERIFIED' if (
                'all three' in position or 'jointly' in position or 'together' in position
            ) else 'AT_ODDS'
        if subject == 'without_prejudice':
            return 'VERIFIED' if (
                'soft' in position or 'conciliatory' in position or 'gentle' in position
            ) else 'AT_ODDS'
    if subject in oi_subjects:
        if subject == 'right_of_first_refusal':
            return 'VERIFIED' if position in {
                'agreed by the father', 'father agreed', 'full',
            } else 'AT_ODDS'
        if subject == 'children_named':
            return 'VERIFIED' if position in {
                'both children, with their ages', 'both children with ages',
                'both with ages',
            } else 'AT_ODDS'
        if subject == 'overnight_stays':
            return 'VERIFIED' if position in {
                'several occasions at her home or with a sitter',
                'home or sitter both', 'full',
            } else 'AT_ODDS'
        if subject == 'inconsistent_accounts':
            return 'VERIFIED' if position in {'all four', 'all four audiences'} else 'AT_ODDS'
        if subject == 'sender_signature':
            return 'VERIFIED' if position in {
                'own name', 'full name', "the sender's own name",
            } else 'AT_ODDS'
    return 'NOT_IN_RECORD'

out_rows = []
counts = Counter()
clarification_count = 0
for r in rows:
    subject = r['subject']
    position = r['position']
    if subject in cl_subjects:
        entry = cl_subjects[subject]
        clarification_count += 1
    elif subject in oi_subjects:
        entry = oi_subjects[subject]
    else:
        entry = 'NONE'
    v = verdict(subject, position)
    counts[v] += 1
    out_rows.append({'line_id': r['line_id'], 'verdict': v, 'record_entry': entry})

with open('letter_line_review.csv', 'w', newline='') as f:
    w = csv.DictWriter(f, fieldnames=['line_id', 'verdict', 'record_entry'])
    w.writeheader()
    w.writerows(out_rows)

results = {
    'verified_count': counts['VERIFIED'],
    'at_odds_count': counts['AT_ODDS'],
    'not_in_record_count': counts['NOT_IN_RECORD'],
    'clarification_governed_count': clarification_count,
}
with open('results.json', 'w') as f:
    json.dump(results, f, indent=2)
    f.write('\n')

answer = f"""# Review of the draft letter against the client's record

I weighed every numbered line in `input/letter_lines.csv` against the client's first message and later clarification, using `input/review_protocol.md` to decide which record entry governs each subject. Where the clarification speaks to a subject, that later entry prevails over the original instruction, and the line is judged against the clarification alone. Where the clarification leaves a subject untouched, the original entry still governs. Where neither record speaks to a subject, the line is not in the record at all, however reasonable it may read.

The review shows that the draft frequently departs from the record. Some lines repeat the client's actual position, but many reverse it, narrow it, or address a person the client corrected. The addressee error is the clearest example: the client explained that the letter goes to the mother's attorney, not the father's, yet several lines still direct it to Mr Adler's counsel. Other lines drop required limbs from compound positions, such as the overnight-stay, inconsistent-accounts, and behavioural-plan entries, so they are at odds even when they sound close. Lines on subjects the record never addresses cannot be verified.

Letter lines at odds with the record: {counts['AT_ODDS']}

In all, {counts['VERIFIED']} lines are verified by the record, {counts['AT_ODDS']} are at odds with the record, and {counts['NOT_IN_RECORD']} are not in the record at all. Of the governing entries, {clarification_count} come from the clarification rather than the original instruction. The per-line table records each verdict and the entry that governs it.
"""
with open('answer.md', 'w') as f:
    f.write(answer)

print('Wrote deliverables.')
print('counts:', dict(counts))
print('clarification_governed_count:', clarification_count)
